/*
 * A170984  Expansion of (Product_{i=1..m-1} (1 + x^(4*i-1))) * (1 +
 *          x^(2*m-1)) for m = 12.
 * https://oeis.org/A170984
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, fini, full, easy
 * Formula:   a(n) is the coefficient of x^n in (product_{i=1..11} (1 +
 *            x^(4*i-1))) * (1 + x^(23)) for m = 12. The polynomial is
 *            generated by the multiset {3,7,11,15,19,23,23,27,31,35,39,43}
 * Range:     u8 n <= 276, u16 n <= 276, u32 n <= 276, u64 n <= 276,
 *            u128 n <= 276, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdbool.h>

seq_t a(idx_t n)
{
    static seq_t coeff[277];
    static bool initialized = false;
    const idx_t maxdeg   = 276;
    static const idx_t exps[12] = {
        3, 7, 11, 15, 19, 23, 23, 27, 31, 35, 39, 43
    };

    if (!initialized) {
        /* Initialise all coefficients to zero. */
        for (idx_t i = 0; i <= maxdeg; ++i)
            coeff[i] = 0;

        coeff[0] = 1;  /* empty subset */

        /* Dynamic programming: each factor (1 + x^e) doubles the number
           of ways to obtain each degree. */
        for (idx_t j = 0; j < 12; ++j) {
            idx_t e = exps[j];
            for (idx_t i = maxdeg; i >= e; --i) {
                coeff[i] = coeff[i] + coeff[i - e];
            }
        }

        initialized = true;
    }

    if (n > maxdeg)
        return 0;
    return coeff[n];
}
